function aiActionsBatch_extractJsonCandidate(rawText) {
  const text = typeof rawText === 'string' ? rawText : '';
  const fencedMatches = [...text.matchAll(/```(?:json)?\s*([\s\S]*?)```/gi)];
  const sources = fencedMatches.length ? fencedMatches.map(match => match[1] || '') : [text];

  const collectCandidates = source => {
    const candidates = [];
    let start = -1;
    let stack = [];
    let inString = false;
    let escaped = false;

    for (let index = 0; index < source.length; index++) {
      const char = source[index];

      if (inString) {
        if (escaped) {
          escaped = false;
        } else if (char === '\\') {
          escaped = true;
        } else if (char === '"') {
          inString = false;
        }
        continue;
      }

      if (char === '"') {
        inString = true;
        continue;
      }

      if (start < 0) {
        if (char === '{' || char === '[') {
          start = index;
          stack = [char];
        }
        continue;
      }

      if (char === '{' || char === '[') {
        stack.push(char);
        continue;
      }

      if (char === '}' || char === ']') {
        const expected = char === '}' ? '{' : '[';
        if (!stack.length || stack[stack.length - 1] !== expected) {
          start = -1;
          stack = [];
          continue;
        }

        stack.pop();
        if (stack.length === 0 && start >= 0) {
          const candidate = source.slice(start, index + 1).trim();
          if (candidate) {
            candidates.push(candidate);
          }
          start = -1;
        }
      }
    }

    return _.uniq(candidates);
  };

  const normalizeParsedPayload = parsed => {
    if (Array.isArray(parsed?.entries)) return parsed.entries;
    if (Array.isArray(parsed?.result?.entries)) return parsed.result.entries;
    if (Array.isArray(parsed)) return parsed;
    if (aiActionsBatch_isPlainObject(parsed) && Number.isFinite((0,utils/* ensureNumericUID */.gl)(parsed.uid))) return [parsed];
    throw new Error('JSON 根节点不是 entries 数组');
  };

  for (const source of sources) {
    const candidates = collectCandidates(source);
    for (const candidate of candidates) {
      try {
        normalizeParsedPayload(JSON.parse(candidate));
        return candidate;
      } catch {
        // try next candidate
      }
    }

    if (candidates.length) {
      return candidates[0];
    }
  }

  const firstBrace = text.indexOf('{');
  const lastBrace = text.lastIndexOf('}');
  if (firstBrace >= 0 && lastBrace > firstBrace) {
    return text.slice(firstBrace, lastBrace + 1).trim();
  }

  return text.trim();
}

function repairJsonCandidate(candidate) {
  if (typeof candidate !== 'string' || !candidate) {
    return candidate;
  }

  let repaired = '';
  let inString = false;
  let escaped = false;

  const peekNextNonWhitespace = startIndex => {
    for (let index = startIndex; index < candidate.length; index += 1) {
      const char = candidate[index];
      if (!/\s/.test(char)) {
        return char;
      }
    }
    return '';
  };

  for (let index = 0; index < candidate.length; index += 1) {
    const char = candidate[index];

    if (!inString) {
      repaired += char;
      if (char === '"') {
        inString = true;
      }
      continue;
    }

    if (escaped) {
      repaired += char;
      escaped = false;
      continue;
    }

    if (char === '\\') {
      repaired += char;
      escaped = true;
      continue;
    }

    if (char === '"') {
      const nextNonWhitespace = peekNextNonWhitespace(index + 1);
      if (!nextNonWhitespace || nextNonWhitespace === ',' || nextNonWhitespace === '}' || nextNonWhitespace === ']' || nextNonWhitespace === ':') {
        repaired += char;
        inString = false;
      } else {
        repaired += '\\"';
      }
      continue;
    }

    repaired += char;
  }

  return repaired;
}

